-- auth-svc: OIDC providers and the external identities linked to users, in the auth_svc schema
-- Design: docs/design/oidc-v0.md (WBS-4.1).

-- id is a UUIDv7 generated by the service. slug is part of the redirect URI
-- registered at the provider (/api/auth/oidc/<slug>/callback), so it follows
-- the team-name rule and never changes. client_secret_sealed is the client
-- secret encrypted with GIT2_SECRET_KEY (internal/secretbox), bound to this
-- row's id; the key is never stored here.
CREATE TABLE IF NOT EXISTS auth_svc.oidc_providers (
    id                   UUID         PRIMARY KEY,
    slug                 VARCHAR(39)  NOT NULL,
    display_name         VARCHAR(100) NOT NULL,
    issuer               TEXT         NOT NULL,
    client_id            TEXT         NOT NULL,
    client_secret_sealed BYTEA        NOT NULL,
    enabled              BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT oidc_providers_slug_key  UNIQUE (slug),
    CONSTRAINT oidc_providers_slug_rule CHECK (slug ~ '^[a-z0-9][a-z0-9_-]{2,38}$')
);

-- An identity is the provider's subject (the "sub" claim), linked to one
-- git2 user. A user has at most one identity per provider. email is what the
-- provider last said, for the admin's information; it is never used to find
-- the user again. Deleting a provider deletes its links, never the users;
-- users are disabled, never deleted, so a user with links cannot be removed
-- by accident.
CREATE TABLE IF NOT EXISTS auth_svc.user_identities (
    provider_id     UUID        NOT NULL,
    subject         TEXT        NOT NULL,
    user_id         UUID        NOT NULL,
    email           TEXT        NOT NULL DEFAULT '',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_sign_in_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT user_identities_pkey PRIMARY KEY (provider_id, subject),
    CONSTRAINT user_identities_provider_user_key UNIQUE (provider_id, user_id),
    CONSTRAINT user_identities_provider_fkey FOREIGN KEY (provider_id)
        REFERENCES auth_svc.oidc_providers (id) ON DELETE CASCADE,
    CONSTRAINT user_identities_user_fkey FOREIGN KEY (user_id)
        REFERENCES auth_svc.users (id) ON DELETE RESTRICT
);

-- "Which identities does this user have?" for the admin user page.
CREATE INDEX IF NOT EXISTS user_identities_user_id_idx
    ON auth_svc.user_identities (user_id);
